INSERT INTO translations (language_code, translation_key, translation_value) VALUES ('ta', 'goToCharacter', 'அடுத்த எழுத்துக்கு செல்லுங்கள். நீங்கள் முந்தைய நிலைகளை அவர்களின் எழுத்துக்களை அணுகி மறுபார்வை செய்யலாம் ஆனால் நீங்கள் நிலைகளை தவிர்க்க முடியாது') ON CONFLICT (language_code, translation_key) DO UPDATE SET translation_value = EXCLUDED.translation_value;
INSERT INTO translations (language_code, translation_key, translation_value) VALUES ('ta', 'findNextCharacter', 'நீங்கள் நிலை {level} முடித்துவிட்டீர்கள்! நல்ல வேலை. இப்போது {character} கண்டுபிடிப்போம்') ON CONFLICT (language_code, translation_key) DO UPDATE SET translation_value = EXCLUDED.translation_value;
INSERT INTO translations (language_code, translation_key, translation_value) VALUES ('ta', 'levelRestriction', 'இந்த எழுத்து நிலை {level} க்கானது. முந்தைய நிலைகளை முதலில் முடிக்கவும்.') ON CONFLICT (language_code, translation_key) DO UPDATE SET translation_value = EXCLUDED.translation_value;
INSERT INTO translations (language_code, translation_key, translation_value) VALUES ('ta', 'dialogueControls', 'மீண்டும் முயற்சி செய்ய ரிட்டர்ன் பட்டனை கிளிக் செய்யுங்கள் அல்லது உச்சரிப்பு கேட்க சவுண்ட் பட்டனை கிளிக் செய்யுங்கள். நீங்கள் எந்த வார்த்தையிலும் கிளிக் செய்து இந்த வார்த்தை பற்றிய தகவலை கண்டுபிடிக்கலாம் (அல்லது வார்த்தைகளின் குழுவை தேர்வு செய்யுங்கள்)') ON CONFLICT (language_code, translation_key) DO UPDATE SET translation_value = EXCLUDED.translation_value;
