INSERT INTO translations (language_code, translation_key, translation_value) VALUES ('ta', 'aiDialogueDescription', 'AI-உருவாக்கப்பட்ட உரையாடல்கள் சோதனை ரீதியானவை மற்றும் தரத்தில் வேறுபடலாம். அவை உரையாடலுக்கு தேவையான அனைத்து சொல்லகராதி சொற்களையும் உள்ளடக்கும்') ON CONFLICT (language_code, translation_key) DO UPDATE SET translation_value = EXCLUDED.translation_value;
